template<int n> struct vec {
    double data[n] = {0};
    double& operator[](const int i) { return data[i]; }
    double operator[](const int i) const { return data[i]; }
};

template<int nrows,int ncols> struct mat {
    vec<ncols> rows[nrows] = {{}};
    vec<ncols>& operator[] (const int idx) { return rows[idx]; }
    const vec<ncols>& operator[] (const int idx) const { return rows[idx]; }
};

typedef mat<3,3> mat3;

double mat3_cofactor(const mat3& m, const int row, const int col) {
    int r1 = (row + 1) % 3;
    int r2 = (row + 2) % 3;
    int c1 = (col + 1) % 3;
    int c2 = (col + 2) % 3;
    double det = m[r1][c1] * m[r2][c2] - m[r1][c2] * m[r2][c1];
    return ((row + col) % 2 == 0) ? det : -det;
}

int main() {
    mat3 m;
    m[0][0] = 1; m[0][1] = 2; m[0][2] = 3;
    m[1][0] = 0; m[1][1] = 4; m[1][2] = 5;
    m[2][0] = 1; m[2][1] = 0; m[2][2] = 6;

    // Cofactor(0,0) = + (4*6 - 5*0) = 24
    assert(mat3_cofactor(m, 0, 0) == 24);
    // Cofactor(0,1) = - (0*6 - 5*1) = 5
    assert(mat3_cofactor(m, 0, 1) == 5);
    // Cofactor(1,1) = + (1*6 - 3*1) = 3
    assert(mat3_cofactor(m, 1, 1) == 3);

    std::cout << "Tests passed!" << std::endl;
    return 0;
}

